export class RequestBuilder {
  constructor() { this.request = { method: 'GET', headers: {}, query: {} }; }
  withMethod(value) { this.request.method = value; return this; } withHeader(k, v) { this.request.headers[k] = v; return this; }
  withQueryParam(k, v) { this.request.query[k] = v; return this; } withBody(body) { this.request.body = body; return this; }
  build() { return structuredClone(this.request); }
}
export class ApiClient {
  constructor(context) { this.context = context; }
  async execute(path, request) { const started = performance.now(); const response = await this.context.fetch(path, { method: request.method, headers: request.headers, params: request.query, ...(request.body === undefined ? {} : { data: request.body }) }); return { status: response.status(), headers: response.headers(), body: await response.json(), responseTimeMs: performance.now() - started }; }
}
export class UserService {
  constructor(client) { this.client = client; }
  getUsers() { return this.client.execute('/users', new RequestBuilder().withMethod('GET').build()); }
  async requestUsers() { this.usersResponse = await this.getUsers(); }
  verifyUsersResponse() { const response = this.usersResponse; if (!response || response.status !== 200 || !Array.isArray(response.body) || response.body.length === 0) throw new Error('Users response was not successful.'); }
  async verifyUsersAvailable() { await this.requestUsers(); this.verifyUsersResponse(); }
}
